function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  // Draw the hills
  brush.fill("#5e4b1d"); // Green for the hills
  brush.beginShape();
  brush.vertex(200, 100); // Top of the hill
  brush.vertex(0, 300); // Left of the hill
  brush.vertex(400, 300); // Right of the hill
  brush.endShape();

  // Draw the sun
  brush.fill("#ff8e46"); // Yellow for the sun
  brush.beginShape();
  brush.vertex(200, 0); // Center of the sun
  brush.vertex(100, 30); // Top of the sun
  brush.vertex(300, 30); // Bottom of the sun
  brush.endShape();

  // Draw the atmosphere
  brush.fill("#7b8b8d"); // Light gray for the atmosphere
  brush.beginShape();
  brush.vertex(200, 200); // Center of the atmosphere
  brush.vertex(100, 300); // Top of the atmosphere
  brush.vertex(300, 300); // Bottom of the atmosphere
  brush.endShape();
}
```

