function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Sky color
  brush.fill("#88d9c1", 100); // Sun color with 100% opacity
  brush.beginShape(1); // Use curvature for a sun shape
  brush.vertex(200, 200 - 50); // Position the sun's center at (200, 200) and draw it
  brush.vertex(100, 100); // Sun's edge point
  brush.vertex(200, 100); // Sun's other edge point
  brush.endShape();

  // Paint green hills
  brush.fill("#a9e8b7", 100); // Green color with 100% opacity
  brush.beginShape(); // Begin a shaped hill with curvature
  brush.vertex(200, 200); // Position the hill's center
  brush.vertex(400, 200); // Right side of the hill
  brush.vertex(300, 180); // Bottom of the hill
  brush.endShape(true);
}

