function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Paint the sky
  brush.fill("#87CEEB"); // Light blue for the sky
  brush.fillBleed(0.1); // Use a light bleed to simulate sunrise
  brush.beginShape();
  brush.vertex(200, 200 - 50); // Sun at the top center
  brush.vertex(200, 150); // Sun at the bottom
  brush.vertex(200, 200); // Sun center
  brush.endShape(true);

  // Paint the hills
  brush.fill("#666633"); // Green color for the hills
  brush.fillBleed(0.1); // Use a light bleed to simulate the sunrise
  brush.beginShape();
  brush.vertex(150, 150); // Left hill
  brush.vertex(100, 150); // Right hill
  brush.vertex(200, 100); // Hills at the bottom
  brush.vertex(150, 150); // Left hill (duplicate)
  brush.endShape(true);

  // Paint the sunset
  brush.fill("#FF4500"); // Orange and red for the sunset
  brush.fillBleed(0.2); // Use a darker bleed to simulate sunset
  brush.beginShape();
  brush.vertex(100, 250); // Left of the sun
  brush.vertex(200, 250); // Center of the sun
  brush.vertex(150, 300); // Right of the sun
  brush.endShape(true);

  // Paint the clouds
  brush.fill("#b3e5fc"); // Light blue for clouds
  brush.fillBleed(0.3); // Use a light bleed
  brush.beginShape();
  brush.vertex(100, 200); // Left cloud
  brush.vertex(150, 150); // Center cloud
  brush.vertex(200, 200); // Right cloud
  brush.endShape(true);

  // Paint the path of the sun
  brush.fill("#ffffff"); // White color for the sun's path
  brush.fillBleed(0.1); // Use a white bleed
  brush.beginShape();
  brush.vertex(200, 100); // Top of the sun path
  brush.vertex(200, 300); // Bottom of the sun path
  brush.endShape(true);
}
```

