function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#81bd92", 1); // Sun
  brush.beginShape();
  brush.vertex(200, 150); // Top of sun
  brush.vertex(100, 100); // Right of sun
  brush.vertex(300, 100); // Bottom of sun
  brush.vertex(400, 50); // Left of sun
  brush.endShape(true);

  brush.fill("#92c077", 0.8); // Sun rays
  brush.beginShape();
  brush.vertex(200, 150); // Top of sun
  brush.vertex(300, 50); // Right of sun
  brush.vertex(100, 50); // Bottom of sun
  brush.vertex(300, 0); // Left of sun
  brush.endShape(true);
  brush.fill("#787062", 1); // Sun disc

  brush.fill("#b39826", 0.5); // Hills
  brush.beginShape();
  brush.vertex(100, 160); // Top of hill
  brush.vertex(200, 30); // Right of hill
  brush.vertex(200, 200); // Bottom of hill
  brush.vertex(400, 200); // Left of hill
  brush.endShape(true); // Hills

  brush.fill("#77b188", 0.7); // Grass
  brush.beginShape();
  brush.vertex(0, 40); // Top of grass
  brush.vertex(0, 0); // Right of grass
  brush.vertex(300, 20); // Bottom of grass
  brush.vertex(400, 0); // Left of grass
  brush.endShape(true); // Grass
}

