  brush.fill("#ff6c32"); // Sun color
  brush.beginShape();
  brush.vertex(200, 50); // Position of the sun
  brush.vertex(200, 50 + 100); // Sun diameter
  brush.vertex(200, 100); // Sun's base
  brush.endShape();      // Paint the sun
}
