function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#54A868", 100);  // Sunset color
  brush.fillTexture(0.7, 0);  // Add a slight texture to the sun

  // Draw hills with the sun in the center
  brush.fill("#062B29", 100);  // Green hills
  brush.beginShape();
  brush.vertex(200, 100);      // Top of the hill
  brush.vertex(200, 120);      // Bottom of the hill
  brush.vertex(150, 140);      // Left side of the hill
  brush.vertex(170, 140);      // Right side of the hill
  brush.endShape();

  // Draw clouds
  brush.fill("#5B8E40", 100);  // Light blue clouds
  brush.beginShape();
  brush.vertex(200, 100);      // Top of the cloud
  brush.vertex(220, 120);      // Bottom of the cloud
  brush.vertex(200, 140);      // Left side of the cloud
  brush.vertex(220, 140);      // Right side of the cloud
  brush.endShape();

  // Draw sun as a circle
  brush.fill("#F4B252", 100);  // Warm sun color
  brush.beginShape();
  brush.vertex(200, 100);      // Center of the sun
  brush.vertex(220, 110);      // Right side of the sun
  brush.vertex(200, 150);      // Left side of the sun
  brush.vertex(180, 150);      // Back side of the sun
  brush.endShape();
}
